with filtered as (select *, concat_ws('-', dept_name, location) dept_name_location_key, coalesce(location, 'DIRECT') resolved_location from departments where location != 'Singapore') select *, sum(budget) over w_grp running_budget, min(budget) over (partition by location) location_min_budget, avg(budget) over w_recent budget_avg_2_prior, round(budget / sum(budget) over (partition by dept_name), 4) budget_share, lead(budget, 2) over (partition by dept_name order by budget, id) next_budget from filtered window w_grp as (partition by location, dept_name order by budget, id rows between unbounded preceding and current row), w_recent as (partition by location, dept_name order by budget, id rows between 2 preceding and 1 preceding);
